/* Local anonymous evidence log. Photos are not persisted by this module. */
(()=>{
 'use strict';
 const D=window.SCHOOL_DIAGNOSTICS,T=window.SCHOOL_SCAN_TOOLS,KEY='school-diagnostic-evidence-v1';let confirmedText='',report=null,assignmentId='',log=[];
 try{log=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(log))log=[];}catch{}
 const lookup=id=>{if(!id)return null;for(const t of C.topics){const index=C.questions(t.id).findIndex(q=>q.id===id);if(index>=0)return {topic:t,index,question:C.questions(t.id)[index]};}return null;};
 const hash=s=>{let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return (h>>>0).toString(36);};
 const confirmed=()=>!!state.scanText.trim()&&confirmedText===state.scanText;
 const evidenceHTML=e=>`<article class="diagnostic-error"><span class="eyebrow">СТРОКА ${e.index+1}</span><h3>${esc(e.definition.description)}</h3>${e.previousLine?`<p>Предыдущая строка: <code>${esc(e.previousLine)}</code></p>`:''}<pre>${esc(e.line)}</pre><p>${esc(e.explanation)}</p><div class="diagnostic-rule"><b>Правило</b><p>${esc(e.definition.diagnostic_rule)}</p><b>Как проверить</b><p>${esc(e.correction)}</p></div><p>Навык: ${esc(e.definition.topic)}. Это одна наблюдаемая ошибка. Устойчивый пробел оценивается по нескольким независимым работам.</p></article>`;
 const miniTasks=[{id:'signed-1',prompt:'Вычисли 3 − 8.',expression:'3-8',skill:'signed_numbers',title:'Действия с отрицательными числами',difficulty:1},{id:'signed-2',prompt:'Вычисли −4 + 9.',expression:'-4+9',skill:'signed_numbers',title:'Действия с отрицательными числами',difficulty:1},{id:'equation-1',prompt:'Реши 3x + 4 = 19. Запиши корень.',equation:'3x+4=19',skill:'equation_root',title:'Проверка корня уравнения',difficulty:2}];
 function reportHTML(){if(!report)return '';return `<section class="card diagnostic-report" id="diagnosticReport"><span class="eyebrow">АЛГОРИТМИЧЕСКАЯ ПРОВЕРКА · MVP</span><h2>${report.status==='error'?'Найдена проверяемая ошибка':report.status==='correct'?'Поддерживаемые строки проверены':'Нужны дополнительные данные или проверка учителя'}</h2><p>${esc(report.message)}</p>${report.errors?.map(evidenceHTML).join('')||''}${report.unsupported?.length?`<details><summary>Какие строки не удалось проверить</summary><pre>${esc(report.unsupported.join('\n'))}</pre></details>`:''}${report.status==='error'?`<div class="diagnostic-mini"><h3>Проверим основу на других заданиях</h3><p>Эти задания проверяют отдельные навыки. Ошибка в основной работе сама по себе не доказывает проблему с основой.</p>${miniTasks.map(m=>`<div class="mini-task"><label for="mini-${m.id}">${m.prompt}</label><div><input id="mini-${m.id}" class="input" autocomplete="off" aria-label="Ответ: ${esc(m.prompt)}"><button class="btn btn-light" data-diagnostic-mini="${m.id}">Проверить</button></div><p id="mini-result-${m.id}" role="status"></p></div>`).join('')}</div>`:''}<p class="response-note">Поддерживается точная арифметика с дробями и десятичными числами, степени чисел и линейные уравнения с одной переменной. Переменная в знаменателе, нелинейные уравнения, неравенства, доказательства и свободные тексты требуют ручной проверки.</p><button class="btn btn-light" data-go="profile">Открыть карту навыков</button></section>`;}
 document.addEventListener('school-photo-changed',()=>{confirmedText='';report=null;});
 const originalScan=scan;
 scan=()=>{const known=lookup(assignmentId),controls=`<section class="card diagnostic-controls"><h2>Проверка решения по правилам</h2><p>Для проверки переходов оставь одно решение. Разные задачи проверяй отдельно. Проверь каждую строку: программа не исправляет числа и знаки догадкой.</p><label class="review-check"><input type="checkbox" id="confirmOcrText" ${confirmed()?'checked':''}>Я сравнил текст с фотографией и исправил ошибки распознавания</label><label class="field-label" for="knownAssignment">Код задания с сайта, если он есть</label><input class="input" id="knownAssignment" value="${esc(assignmentId)}" placeholder="Например, код из карточки" maxlength="100">${known?`<div class="known-assignment"><b>${esc(known.topic.title)}</b><p>${esc(known.question.prompt)}</p><button class="btn-link" data-return-assignment>Вернуться к карточке</button></div>`:''}<p>По коду можно взять цифровое условие и эталон из банка. Без кода проверяются только записанные поддерживаемые равенства и переходы.</p><button class="btn btn-orange" data-diagnostic-verify ${confirmed()?'':'disabled'}>Проверить решение по правилам</button></section>`;return originalScan()+controls+reportHTML();};
 const originalPractice=practice;
 practice=()=>{let html=originalPractice();if(state.practice?.question?.id)html=html.replace('<footer class="learning-footer">','<div class="photo-solution-entry"><button class="btn btn-light" data-work-for-card>Проверить решение по фото</button><span>Условие этой карточки будет известно программе.</span></div><footer class="learning-footer">');return html;};
 function record(event){
  log=log.filter(e=>!(e.skill===event.skill&&e.assignmentKey===event.assignmentKey));log.push({...event,at:Date.now(),confirmed:true,reliability:1});log=log.slice(-500);
  try{localStorage.setItem(KEY,JSON.stringify(log));}catch{toast('Не удалось сохранить карту навыков в браузере.');}
 }
 function recordReport(r,known){
  if(!['correct','error'].includes(r.status))return;
  let skill=r.firstError?.definition.skill_id||'basic_arithmetic',title=r.firstError?.definition.topic||'Проверяемая арифметика';
  const eqLines=state.scanText.split('\n').filter(s=>/[xх].*=/.test(s));
  const firstLine=state.scanText.split('\n').find(s=>s.includes('='));
  const condition=known?.question.id||r.condition||(firstLine?.split('=')[0])||state.scanText;
  const skills=r.status==='correct'&&r.skillsChecked?.length?r.skillsChecked:[skill];
  for(const checkedSkill of skills){const definition=D.definitions.find(d=>d.skill_id===checkedSkill);record({skill:checkedSkill,title:definition?.topic||(checkedSkill==='equation_equivalence'?'Равносильные преобразования':title),assignmentKey:hash(condition.replace(/\s/g,'')),correct:r.status==='correct',code:r.firstError?.code||null,difficulty:eqLines.length?2:1,source:'confirmed_solution',line:r.firstError?.line||null});}
 }
 function skillMap(){
  const ids=[...new Set(log.map(e=>e.skill))];
  return `<section class="card knowledge-map"><span class="eyebrow">ЛОКАЛЬНАЯ КАРТА НАВЫКОВ</span><h2>Что подтверждено работами</h2><p>В карте учитываются только подтверждённые записи и поддерживаемые проверки. Отсутствие результата означает недостаток данных, а не нулевые знания.</p>${ids.length?ids.map(id=>{const es=log.filter(e=>e.skill===id),a=D.assess(es),title=es.at(-1).title;return `<article class="skill-assessment"><div><h3>${esc(title)}</h3><span class="skill-status">${esc(a.label)}</span></div><div class="skill-evidence"><b>${a.count<3?'Пока рано оценивать':a.score+' / 100'}</b><span>${a.count} ${a.count%100>=11&&a.count%100<=14?'независимых заданий':a.count%10===1?'независимое задание':a.count%10>=2&&a.count%10<=4?'независимых задания':'независимых заданий'}</span></div><p>${esc(a.next||'Реши несколько новых заданий.')}</p><details><summary>История и основание оценки</summary><p>Взвешенная доля правильных проверок. Вес зависит от надёжности, сложности и давности; период полуснижения веса составляет ${D.config.halfLifeDays} дней. Это индекс, а не вероятность освоения.</p>${es.slice(-10).reverse().map(e=>`<p>${new Date(e.at).toLocaleDateString('ru-RU')} · ${e.correct?'Проверено верно':esc(e.code||'Ошибка')}${e.line?` · <code>${esc(e.line)}</code>`:''}</p>`).join('')}</details></article>`;}).join(''):'<div class="empty">Подтверждённых проверок пока нет. Начни с разбора своей работы.</div>'}<p class="response-note">Карта хранится только в этом браузере без имени ученика и без фотографий. Для повторяющегося типа ошибки нужны минимум три независимых задания за последние 180 дней. Индекс показывается после трёх заданий. Для статуса освоения нужны минимум пять заданий, разные уровни сложности и устойчивые последние результаты.</p></section>`;
 }
 const originalProfile=profile;profile=()=>originalProfile()+skillMap();
 document.addEventListener('input',e=>{if(e.target.id==='scanText'){confirmedText='';report=null;const checkbox=document.getElementById('confirmOcrText');if(checkbox)checkbox.checked=false;const button=document.querySelector('[data-diagnostic-verify]');if(button)button.disabled=true;}if(e.target.id==='knownAssignment')assignmentId=e.target.value.trim();});
 document.addEventListener('change',e=>{if(e.target.id==='confirmOcrText'){confirmedText=e.target.checked?state.scanText:'';render();}if(e.target.id==='photoInput'){confirmedText='';report=null;}});
 document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-work-for-card')){assignmentId=state.practice?.question.id||'';confirmedText='';report=null;go('scan');return;}
  if(b.hasAttribute('data-return-assignment')){const known=lookup(assignmentId);if(known)startCard(known.topic.id,known.index);return;}
  if(b.hasAttribute('data-diagnostic-verify')){const known=assignmentId?lookup(assignmentId):null;if(assignmentId&&!known){toast('Код задания не найден. Проверь его или оставь поле пустым.');return;}report=D.verify(state.scanText,{confirmed:confirmed(),assignment:known?.question});if(known?.question.teacherOnly&&report.status==='correct')report={...report,status:'teacher_required',message:'Поддерживаемые вычисления проверены. Полное исходное задание требует содержательной проверки учителем.'};recordReport(report,known);render();document.getElementById('diagnosticReport')?.scrollIntoView({behavior:'smooth'});return;}
  if(b.hasAttribute('data-diagnostic-mini')){
   const m=miniTasks.find(x=>x.id===b.dataset.diagnosticMini),input=m&&document.getElementById('mini-'+m.id);if(!m||!input?.value.trim())return;
   let correct=false;try{const got=D.parse(input.value);if(got.a.n!==0n)throw 0;const expected=m.equation?D.equation(m.equation).root:D.parse(m.expression).b;correct=D.textQ(got.b)===D.textQ(expected);}catch{document.getElementById('mini-result-'+m.id).textContent='Введи число или дробь; эту запись проверить не удалось.';return;}
   record({skill:m.skill,title:m.title,assignmentKey:m.id,correct,code:correct?null:'KNOWN_SCALAR_WRONG',difficulty:m.difficulty,source:'diagnostic_mini'});document.getElementById('mini-result-'+m.id).textContent=correct?'Верно. Это отдельное подтверждение навыка.':'Ответ не совпал. Проверь вычисления; причина по одному итогу не устанавливается.';
  }
 });
 window.SCHOOL_KNOWLEDGE_MAP={skills:()=>[...new Set(log.map(e=>e.skill))].map(skill=>({skill,...D.assess(log.filter(e=>e.skill===skill))})),events:()=>log.map(e=>({...e}))};
 render();
})();
